-- Socle initial. Les données existantes dans gm_app ne sont pas modifiées.
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text not null default '', email text not null default '', phone text, country text, nationality text, avatar_url text, created_at timestamptz not null default now());
create table public.user_roles (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, role text not null check (role in ('super_admin','admin','editor','scholarship_manager','academic_advisor','application_manager','visa_manager','training_manager','student')), created_at timestamptz not null default now(), unique(user_id,role));
create function public.has_role(roles text[]) returns boolean language sql stable security definer set search_path=public,pg_temp as $$ select exists(select 1 from public.user_roles where user_id=auth.uid() and role=any(roles)) $$;
revoke all on function public.has_role(text[]) from public;
grant execute on function public.has_role(text[]) to anon, authenticated;
create function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$ begin insert into public.profiles(id,full_name,email) values(new.id, left(coalesce(new.raw_user_meta_data->>'full_name',''),120), coalesce(new.email,'')); insert into public.user_roles(user_id,role) values(new.id,'student'); return new; end $$;
create trigger gm_new_user after insert on auth.users for each row execute function public.handle_new_user();
create table public.scholarships (id uuid primary key default gen_random_uuid(), title text not null, slug text not null unique, description text not null default '', country text, institution text, degree_level text, fields_of_study text, eligible_nationalities text, funding_type text, benefits text, requirements text, required_documents text, opening_date date, deadline date, official_url text, source_url text, verification_date date, status text not null default 'draft' check(status in ('draft','published','archived')), created_by uuid references auth.users(id), created_at timestamptz not null default now());
create index scholarships_status_created_idx on public.scholarships(status,created_at desc);
create table public.favorites (user_id uuid not null references auth.users(id) on delete cascade, scholarship_id uuid not null references public.scholarships(id) on delete cascade, created_at timestamptz not null default now(), primary key(user_id,scholarship_id));
create table public.countries (id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique, description text, education_system text, language text, visa_information text, image_url text, published boolean not null default false);
create table public.universities (id uuid primary key default gen_random_uuid(), name text not null, country_id uuid references public.countries(id), city text, description text, website text, logo_url text, programs text, admission_requirements text, tuition_information text, status text not null default 'draft' check(status in ('draft','published')));
create table public.programs (id uuid primary key default gen_random_uuid(), university_id uuid references public.universities(id) on delete cascade, name text not null, degree_level text, field text, duration text, language text, description text);
create table public.articles (id uuid primary key default gen_random_uuid(), title text not null, slug text not null unique, content text not null default '', cover_image text, category text, author_id uuid references auth.users(id), publication_status text not null default 'draft' check(publication_status in ('draft','published')), published_at timestamptz);
create table public.testimonials (id uuid primary key default gen_random_uuid(), student_name text not null, content text not null, photo_url text, consent_status boolean not null default false, publication_status text not null default 'draft' check(publication_status in ('draft','published')));
create table public.orientation_requests (id uuid primary key default gen_random_uuid(), student_id uuid not null references auth.users(id) on delete cascade, academic_background text, grades text, preferred_fields text, preferred_countries text, budget text, languages text, career_project text, status text not null default 'recu', assigned_advisor uuid references auth.users(id), created_at timestamptz not null default now());
create index orientation_student_idx on public.orientation_requests(student_id);
create table public.contact_requests (id uuid primary key default gen_random_uuid(), name text not null check(length(name) between 2 and 120), email text not null check(length(email) between 3 and 190), phone text, message text not null check(length(message) between 5 and 5000), consent boolean not null check(consent), created_at timestamptz not null default now());
alter table public.profiles enable row level security;
alter table public.user_roles enable row level security;
alter table public.scholarships enable row level security;
alter table public.favorites enable row level security;
alter table public.countries enable row level security;
alter table public.universities enable row level security;
alter table public.programs enable row level security;
alter table public.articles enable row level security;
alter table public.testimonials enable row level security;
alter table public.orientation_requests enable row level security;
alter table public.contact_requests enable row level security;
create policy profiles_self_read on public.profiles for select to authenticated using (id=auth.uid() or public.has_role(array['super_admin','admin']));
create policy profiles_self_update on public.profiles for update to authenticated using (id=auth.uid()) with check (id=auth.uid());
create policy roles_read on public.user_roles for select to authenticated using (user_id=auth.uid() or public.has_role(array['super_admin']));
create policy roles_insert on public.user_roles for insert to authenticated with check (public.has_role(array['super_admin']) and user_id<>auth.uid());
create policy roles_delete on public.user_roles for delete to authenticated using (public.has_role(array['super_admin']) and user_id<>auth.uid());
create policy scholarships_read on public.scholarships for select to anon,authenticated using (status='published' or public.has_role(array['super_admin','admin','scholarship_manager']));
create policy scholarships_staff on public.scholarships for all to authenticated using (public.has_role(array['super_admin','admin','scholarship_manager'])) with check (public.has_role(array['super_admin','admin','scholarship_manager']));
create policy favorites_own on public.favorites for all to authenticated using (user_id=auth.uid()) with check (user_id=auth.uid() and exists(select 1 from public.scholarships where id=scholarship_id and status='published'));
create policy countries_read on public.countries for select to anon,authenticated using (published);
create policy universities_read on public.universities for select to anon,authenticated using (status='published');
create policy programs_read on public.programs for select to anon,authenticated using (exists(select 1 from public.universities where id=university_id and status='published'));
create policy articles_read on public.articles for select to anon,authenticated using (publication_status='published' and published_at<=now());
create policy testimonials_read on public.testimonials for select to anon,authenticated using (publication_status='published' and consent_status);
create policy orientation_insert on public.orientation_requests for insert to authenticated with check (student_id=auth.uid() and assigned_advisor is null and status='recu');
create policy orientation_read on public.orientation_requests for select to authenticated using (student_id=auth.uid() or assigned_advisor=auth.uid() or public.has_role(array['super_admin','admin']));
create policy orientation_staff_update on public.orientation_requests for update to authenticated using (public.has_role(array['super_admin','admin'])) with check (public.has_role(array['super_admin','admin']));
create policy contact_insert on public.contact_requests for insert to anon,authenticated with check (consent);
create policy contact_read on public.contact_requests for select to authenticated using (public.has_role(array['super_admin','admin']));
